  /* :process/spawn: only when the grant names wire 20, and only with a
   * well-formed :process/spawn grant (an absent one grants no program). */
  if (kexe_cap_admitted(shared->context.allow, 20)) {
    if (kexe_spawn_grant_init() != 0) {
      fprintf(stderr, "kexe-loader: malformed :process/spawn grant (KEXE_CAP_RESOURCES_20 / KEXE_SPAWN_ENV / KEXE_SPAWN_PATH_LOOKUP)\n");
      return 2;
    }
    if (pipe(kspawn_req_pipe) != 0 || pipe(kspawn_resp_pipe) != 0) fail("spawn broker pipe");
    kspawn_broker_active = 1;
  }
  kexe_entropy_granted = kexe_cap_admitted(shared->context.allow, 23);
  /* Native TCP: only when the grant names one of wires 43..47, and only with
   * well-formed address scopes (an absent one grants no address). */
  if (kexe_cap_admitted(shared->context.allow, 43) || kexe_cap_admitted(shared->context.allow, 44) ||
      kexe_cap_admitted(shared->context.allow, 45) || kexe_cap_admitted(shared->context.allow, 46) ||
      kexe_cap_admitted(shared->context.allow, 47)) {
    if (knet_grant_init() != 0) {
      fprintf(stderr, "kexe-loader: malformed native TCP grant (KEXE_CAP_RESOURCES_43 / KEXE_CAP_RESOURCES_45: comma-separated <ipv4>:<port>)\n");
      return 2;
    }
    if (pipe(knet_req_pipe) != 0 || pipe(knet_resp_pipe) != 0) fail("net broker pipe");
    knet_broker_active = 1;
  }
#ifdef KEXE_GPU_VULKAN
  /* :gpu/compute: only when the grant names wire 42. The pipes exist before
   * the fork so both sides hold them; the supervisor serves, the guest asks. */
  if (kexe_cap_admitted(shared->context.allow, 42)) {
    if (pipe(kgpu_req_pipe) != 0 || pipe(kgpu_resp_pipe) != 0) fail("gpu broker pipe");
    kgpu_broker_active = 1;

pid_t child = fork();
if (child < 0) fail("fork");
if (child > 0) {
  int child_status = supervise(child);
  report_budget_trap(shared, child_status);
  if (kexe_census_sites != NULL) kexe_arena_census(shared, getenv("KEXE_ARENA_CENSUS"));
  if (kexe_use != NULL) {
    /* KEXE_ARENA_USE: one EDN line on stderr -- the high-water mark of each
     * arena (the final use, or the largest use seen before an arena-scope
     * release, whichever is larger) and what the vector conj path did. */
    uint64_t peak_pairs = shared->pair_used > kexe_use->peak_pairs ? shared->pair_used : kexe_use->peak_pairs;
    uint64_t peak_pool = shared->string_pool_used > kexe_use->peak_string_pool ? shared->string_pool_used : kexe_use->peak_string_pool;
    uint64_t peak_vectors = shared->vector_used > kexe_use->peak_vectors ? shared->vector_used : kexe_use->peak_vectors;
    uint64_t peak_items = shared->vector_item_used > kexe_use->peak_vector_items ? shared->vector_item_used : kexe_use->peak_vector_items;
    fprintf(stderr,
            "KEXE_ARENA_USE {:pairs %" PRIu64 " :string-pool-bytes %" PRIu64
            " :vectors %" PRIu64 " :vector-items %" PRIu64
            " :heap-bytes %" PRIu64
            " :conj %" PRIu64 " :conj-tail %" PRIu64 " :conj-region %" PRIu64
            " :conj-copy %" PRIu64 " :copied-words %" PRIu64
            " :reserved-words %" PRIu64 " :regions %" PRIu64
            " :scope-releases %" PRIu64
            " :string-regions %" PRIu64 " :string-region-appends %" PRIu64
            " :string-copied-bytes %" PRIu64 " :string-reserved-bytes %" PRIu64 "}\n",
            peak_pairs, peak_pool, peak_vectors, peak_items,
            peak_pairs * (uint64_t)sizeof(struct kexe_pair_v1) + peak_pool +
                peak_vectors * (uint64_t)sizeof(struct kexe_vector_v1) +
                peak_items * 8u,
            kexe_use->conj_calls, kexe_use->conj_tail, kexe_use->conj_region,
            kexe_use->conj_copy, kexe_use->copied_words,
            kexe_use->reserved_words, kexe_use->regions,
            kexe_use->scope_releases, kexe_use->string_regions,
            kexe_use->string_region_appends, kexe_use->string_copied_bytes,
            kexe_use->string_reserved_bytes);
    if (kexe_hashcons != NULL)
      fprintf(stderr, "KEXE_HASHCONS {:entries-log2 %u :ways %u :pair-hits %" PRIu64 " :empty-vector-shared %" PRIu64 "}\n",
              kexe_hashcons_bits, KEXE_HASHCONS_WAYS, kexe_use->hashcons_hits, kexe_use->empty_vector_shared);
  }
  if (structured_report)
    child_status = write_supervisor_report(shared, child_status, result_type,
                                           record_field_count,
                                           variant_case_count,
                                           variant_bool_mask);
  if (munmap(shared, sizeof(*shared)) != 0) fail("supervisor shared munmap");
  if (munmap(memory, mapped) != 0) fail("supervisor munmap");

int status = 0;
while (waitpid(child, &status, 0) < 0) {
  if (errno == EINTR) continue;
  fail("waitpid");
}
alarm(0);
supervised_pid = -1;
if (supervisor_timed_out) {
  write_trap_line(KEXE_TRAP_LINE_WALL_TIMEOUT);
  return 122;
}
if (WIFEXITED(status)) return WEXITSTATUS(status);
